from .messages import \
    ApiAlarmMsg, \
    Api2AlarmMsg, \
    ApiSfpStatusIndMsg, \
    FaultRequest, \
    FaultIndication, \
    LomFaultIndication, \
    LomFaultReportIndication, \
    CpuOverloadIndication, \
    MemoryOverloadIndication, \
    OamFaultIndMsg


class FaultTrigger(object):

    def __init__(self, api, timeout):
        self.api = api
        self.timeout = timeout

    def send_hwapi_api_alarm_msg(self, sender, receiver, fault_id, unit_id, *fault_params):
        """Send HWAPI Api Alarm Message"""
        self._send_message(sender, receiver, ApiAlarmMsg(fault_id, unit_id, *fault_params))

    def send_hwapi_api2_alarm_msg(self, sender, receiver, fault_state, fault_id, unit_id, *fault_params):
        """Send HWAPI Api2 Alarm Message"""
        self._send_message(sender, receiver, Api2AlarmMsg(fault_state, fault_id, unit_id, *fault_params))

    def send_hwapi_send_fault_report(self, sender, receiver, fault_id, unit_id, state, severity, object_type, *fault_params):
        """Send HWAPI fault report."""
        self._send_message(sender, receiver, LomFaultReportIndication(fault_id, state, severity, object_type, unit_id, *fault_params))

    def send_hwapi_api_sfp_status_ind_msg(self, sender, receiver, board_id, sfp_connector_id, status_type, status):
        """Send HWAPI ApiSfpStatusIndMsg."""
        self._send_message(sender, receiver, ApiSfpStatusIndMsg(board_id, sfp_connector_id, status_type, status))

    def send_lom_fault_ind_msg(self, sender, receiver, fault_id, state, severity, object_type, unit_id, *fault_params):
        """Send LOM fault indication."""
        self._send_message(sender, receiver, LomFaultIndication(fault_id, state, severity, object_type, unit_id, *fault_params))

    def send_lom_fault_request_msg(self, sender, receiver, fault_id, unit_id, subunit_id, faulty_cpid, state, severity,
                                   object_type, detecting_unit, detecting_subunit, *fault_params):
        """Send LOM fault request."""
        self._send_message(sender, receiver, FaultRequest(
            fault_id, unit_id, subunit_id, faulty_cpid, state, severity, object_type, detecting_unit, detecting_subunit, *fault_params))

    def send_fault_ind_msg(self, sender, receiver, fault_id, state, *fault_params):
        """Send FAULT_IND."""
        self._send_message(sender, receiver, FaultIndication(fault_id, state, sender, *fault_params))

    def send_saa_pro_ce_cpu_load_over_load_ind_msg(
            self, sender, receiver, status, measurment_type, normal_cpu_load, background_cpu_load, irq_cpu_load):
        """Send CPU overload indication."""
        self._send_message(sender, receiver, CpuOverloadIndication(status, measurment_type, normal_cpu_load, background_cpu_load, irq_cpu_load))

    def send_saa_pro_ce_memory_over_load_ind_msg(self, sender, receiver, status, memory_usage):
        """Send memory overload indication."""
        self._send_message(sender, receiver, MemoryOverloadIndication(status, memory_usage))

    def send_oam_fault_ind_msg(self, sender, receiver, fault_id, severity, state, info_type, specific_fault_info):
        """Send OAM_FAULT_IND_MSG."""
        self._send_message(sender, receiver, OamFaultIndMsg(fault_id, severity, state, info_type, specific_fault_info))

    def _send_message(self, sender, receiver, message):
        parameters = {
            "id": message.id,
            "sender": sender,
            "receiver": receiver,
            "payload": message.payload
        }
        self.api.execute_procedure("generateFault", parameters, self.timeout)
